+    /// @dev Below this supply the per-token accumulator would explode (surplus / dust) and
+    ///      later overflow `weight * index` / `acc * keepWeight`; such surplus stays donated.
+    function _minAccrualSupply() internal view returns (uint256) { return 10 ** decimals(); }
@@ function _accrueGlobalYield() internal {
