--- a/contracts/src/abstract/AbstractVotingModule.sol
+++ b/contracts/src/abstract/AbstractVotingModule.sol
@@ struct AbstractVotingModuleStorage {
         mapping(address => uint256) lastCrossChainNonce;
+        /// @notice Highest classic nonce accepted per voter (monotonic)
+        mapping(address => uint256) lastClassicNonce;
